template.query:
subscription SubscribeNodeChanges($tableId: ID) {
  nodeCreated(tableId: $tableId) {
    id
    content
    table {
      id
      identifier
    }
    attributes {
      id
      value
      attribute {
        identifier
        name
        attributeType {
          name
          dataType
        }
      }
    }
    attributeCount
    relationCount
    createdAt
    updatedAt
  }

  nodeUpdated(tableId: $tableId) {
    id
    content
    table {
      id
      identifier
    }
    attributes {
      id
      value
      attribute {
        identifier
        name
      }
    }
    attributeCount
    relationCount
    createdAt
    updatedAt
  }

  nodeDeleted(tableId: $tableId) {
    id
    tableId
    content
    deletedAt
  }
}
